# Auxiliary function: Compare two time stamps.def _compare_timestamps(t1: float, t2: float) -> int:    if abs(t1 - t2) < 0.005:        return 0        if t1 < t2:        return -1    else:        return 1    class VadSegment:    """    Representation of a VAD segement within a recorded session.        Note that the comparison operators for VadSegments are defined such that a VAD segment is less    than another segment if its start time is less than the other segment's start time; in case of    equality we compare the channel IDs, then the end times.        Fields    ------    channel_id: int            The audio channel containing the activity segment (1-based channel ID).    start_time: float        The start time of the segment, measured in seconds elapsed from the beginning of the session.    end_time: float        The end time of the segment, measured in seconds elapsed from the beginning of the session.    confidence: float        The segment confidence (between 0 and 1).    power_spl: float        The mean signal power for the segment, in dB-SPL.    snr_db: float        The mean signal-to-noise ratio for the segment, in dB.    """    def __init__(self, channel: int, start: float, end: float,                 conf: float, power: float, snr: float):        self.channel_id = channel        self.start_time = start        self.end_time = end        self.confidence = conf        self.power_spl = power        self.snr_db = snr            def __eq__(self, other) -> bool:        return (self.channel_id == other.channel_id and                _compare_timestamps(self.start_time, other.start_time) == 0 and                _compare_timestamps(self.end_time, other.end_time) == 0)    def __ne__(self, other) -> bool:        return (self.channel_id != other.channel_id or                _compare_timestamps(self.start_time, other.start_time) != 0 or                _compare_timestamps(self.end_time, other.end_time) != 0)    def __lt__(self, other) -> bool:        res = _compare_timestamps(self.start_time, other.start_time)                if res < 0:            return True        elif res > 0:            return False                if self.channel_id < other.channel_id:            return True        elif self.channel_id > other.channel_id:            return False                return (_compare_timestamps(self.end_time, other.end_time) < 0)    def __le__(self, other) -> bool:        res = _compare_timestamps(self.start_time, other.start_time)                if res < 0:            return True        elif res > 0:            return False                if self.channel_id < other.channel_id:            return True        elif self.channel_id > other.channel_id:            return False                return (_compare_timestamps(self.end_time, other.end_time) <= 0)    def __gt__(self, other) -> bool:        res = _compare_timestamps(self.start_time, other.start_time)                if res > 0:            return True        elif res < 0:            return False                if self.channel_id > other.channel_id:            return True        elif self.channel_id < other.channel_id:            return False                return (_compare_timestamps(self.end_time, other.end_time) > 0)    def __ge__(self, other) -> bool:        res = _compare_timestamps(self.start_time, other.start_time)                if res > 0:            return True        elif res < 0:            return False                if self.channel_id > other.channel_id:            return True        elif self.channel_id < other.channel_id:            return False                return (_compare_timestamps(self.end_time, other.end_time) >= 0)        